import type { PickD3Scale } from '@visx/scale';

import { ChartUnit } from '../../core/types/chart-unit.js';
import type { AxisScaleType } from '../../core/types/scales.js';

export type XYChartScale = PickD3Scale<AxisScaleType, number>;

export type XYChartColorScale = PickD3Scale<AxisScaleType, string>;

/**
 * @internal Props for the xy chart.
 */
export interface XYChartProps {
  /**
   * Data object for the xy chart.
   */
  data: XYChartData[];
  /**
   * Chart height. When a number is specified, it's treated as pixels,
   * otherwise a valid height string is expected.
   * @defaultValue 300px
   */
  height?: number | string;
}

// TODO ADES-6569 - Investigate and take into consideration Grail's response type
export type XYChartData = Record<string, unknown>;

/**
 * @internal Props for the heatmap slot of the xy chart.
 */
export interface XYChartHeatmapSeriesProps {
  /**
   * Data object for the xy chart.
   */
  data?: XYChartData[];
  /**
   * Id required to attach the series to its x-axis.
   */
  xAxisId: string;
  /**
   * Accessor function to retrieve the data for the x0.
   */
  x0Accessor: string;
  /**
   * Accessor function to retrieve the data for the x1.
   */
  x1Accessor: string;
  /**
   * Accessor function to retrieve the data for the y0.
   */
  y0Accessor: string;
  /**
   * Accessor function to retrieve the data for the y1.
   */
  y1Accessor: string;
  /**
   * Accessor function to retrieve the data for the value.
   */
  valueAccessor: string;
}

export type XYChartVariants = XYChartHeatmapSeriesProps[]; // TODO: | XYChartLineSeriesProps[] | ... etc

/**
 * @internal
 * Props for the x-axis of the xy chart.
 */
export interface XYChartAxisProps {
  /**
   * Id for the axis used to bind any series to it.
   */
  id: string;
  /**
   * The data type for the xy chart axis.
   */
  type: XYChartAxisType;
  /**
   * The position for the xy chart axis.
   */
  position: XYChartXAxisPosition;
  /**
   * The unit for the xy chart axis ticks.
   */
  unit?: ChartUnit;
  /**
   * The label to display alongside the axis.
   */
  label?: string;
  /**
   * If true, will visually hide the whole axis.
   * @defaultValue false
   */
  hidden?: boolean;
}

/** The numerical type for the xy chart axis */
export const NUMERICAL_SCALE_TYPE = 'numerical' as const;

/** The data type for the xy chart axis */
export type XYChartAxisType = typeof NUMERICAL_SCALE_TYPE;

/** The bottom position for the xy chart x-axis */
export const BOTTOM_POSITION = 'bottom' as const;

/** The position for the xy chart x-axis */
export type XYChartXAxisPosition = typeof BOTTOM_POSITION;

/** The id for the axis */
export type AxisId = string;

/**
 * @internal
 * Props that represent the extracted slots of the xy chart
 */
export interface XYChartSlots {
  heatmapSeries: XYChartHeatmapSeriesProps[];
  axes: XYChartAxisProps[];
}

/**
 * Props that represent the configuration of the xy chart
 */
export interface XYChartConfiguration {
  heatmapSeries: XYChartHeatmapSeriesProps[];
  axes: XYChartAxisProps[];
}

export interface XYChartVisibleAxesConfig {
  bottom: XYChartAxisProps | undefined;
}

export interface XYChartVisibleAxesScales {
  bottom: XYChartScale | undefined;
}
